"""Explicitly isolated barrier control with confirmation, audit and limits."""

from __future__ import annotations

import json
import logging
import threading
import time
from collections import deque
from pathlib import Path

LOG = logging.getLogger("md_parking_bridge.control")


class ControlError(RuntimeError):
    safe_code = "control_failed"


class ControlDisabled(ControlError):
    safe_code = "control_disabled"


class ConfirmationRequired(ControlError):
    safe_code = "confirmation_required"


class RateLimited(ControlError):
    safe_code = "rate_limited"

    def __init__(self, retry_after: int) -> None:
        super().__init__(self.safe_code)
        self.retry_after = retry_after


class ControlManager:
    """Control actions never run from camera or session refresh code paths."""

    def __init__(
        self,
        enabled: bool,
        cooldown_seconds: int = 15,
        audit_path: Path | None = None,
        audit_limit: int = 100,
    ) -> None:
        self.enabled = enabled
        self.cooldown_seconds = cooldown_seconds
        self._last_attempt: dict[str, float] = {}
        self._audit_path = audit_path
        self._audit: deque[dict] = deque(maxlen=audit_limit)
        self._lock = threading.Lock()
        self._load_audit()

    def configure(self, enabled: bool, cooldown_seconds: int) -> None:
        """Apply safe runtime options without resetting limits or audit."""
        with self._lock:
            self.enabled = enabled
            self.cooldown_seconds = cooldown_seconds

    def _load_audit(self) -> None:
        if self._audit_path is None:
            return
        try:
            value = json.loads(self._audit_path.read_text(encoding="utf-8"))
        except (FileNotFoundError, OSError, UnicodeDecodeError, json.JSONDecodeError):
            return
        if not isinstance(value, list):
            return
        for event in value:
            if (
                isinstance(event, dict)
                and isinstance(event.get("time"), int)
                and isinstance(event.get("barrier_id"), str)
                and event.get("result") in {"accepted", "failed"}
            ):
                self._audit.append(event)

    def _record(self, event: dict) -> None:
        with self._lock:
            self._audit.append(event)
            if self._audit_path is None:
                return
            self._audit_path.parent.mkdir(parents=True, exist_ok=True)
            temporary = self._audit_path.with_suffix(".tmp")
            try:
                temporary.write_text(
                    json.dumps(list(self._audit), separators=(",", ":")),
                    encoding="utf-8",
                )
                temporary.chmod(0o600)
                temporary.replace(self._audit_path)
                self._audit_path.chmod(0o600)
            finally:
                temporary.unlink(missing_ok=True)

    def open(self, bridge, barrier_id: str, confirmed: bool) -> dict:
        if not self.enabled:
            raise ControlDisabled("barrier control is disabled")
        if confirmed is not True:
            raise ConfirmationRequired("explicit confirmation is required")

        with self._lock:
            now = time.monotonic()
            remaining = self.cooldown_seconds - (
                now - self._last_attempt.get(barrier_id, 0)
            )
            if remaining > 0:
                raise RateLimited(max(1, int(remaining + 0.999)))
            self._last_attempt[barrier_id] = now

        timestamp = int(time.time())
        try:
            result = bridge.open_barrier(barrier_id)
            if not isinstance(result, dict) or result.get("status") != "OK":
                raise ControlError("provider did not accept barrier action")
        except Exception:
            event = {
                "time": timestamp,
                "barrier_id": barrier_id,
                "result": "failed",
            }
            self._record(event)
            LOG.warning("barrier action barrier=%s result=failed", barrier_id)
            raise

        event = {
            "time": timestamp,
            "barrier_id": barrier_id,
            "result": "accepted",
        }
        self._record(event)
        LOG.info("barrier action barrier=%s result=accepted", barrier_id)
        return event

    def audit(self) -> list[dict]:
        with self._lock:
            return list(self._audit)
